<script>
$(function(){
 const noteId=$('#gsnForm').data('id'), customers=@json($customers->map(fn($c)=>['id'=>$c->id,'name'=>$c->name])), initial=@json($note?->load(['items.productionOrder.outputProduct.unit','items.customer']));
 const orderModal=new bootstrap.Modal(document.getElementById('gsnOrderModal'));
 const orderTable=$('#gsnOrderTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.goods-sent-notes.orders.dt')),columns:[{data:'number'},{data:'buyer_po_number'},{data:'customer',orderable:false,searchable:false},{data:'style',orderable:false,searchable:false},{data:'item_code',orderable:false,searchable:false},{data:'item_name',orderable:false,searchable:false},{data:'unit',orderable:false,searchable:false},{data:'available_quantity',className:'text-end'},{data:'actions',orderable:false,searchable:false}]});
 function addLine(d){if($('#gsnLines tbody tr[data-order="'+d.id+'"]:not(.empty-line)').length)return;$('#gsnLines .empty-line').remove();let opts='<option value="">—</option>'+customers.map(c=>`<option value="${c.id}" ${String(d.customer_id||'')===String(c.id)?'selected':''}>${$('<div>').text(c.name).html()}</option>`).join('');$('#gsnLines tbody').append(`<tr data-order="${d.id}"><td><input type="hidden" name="items[${d.id}][production_order_id]" value="${d.id}"><input type="hidden" name="items[${d.id}][product_id]" value="${d.product_id}">${$('<div>').text(d.mo).html()}</td><td>${$('<div>').text(d.style).html()}</td><td>${$('<div>').text(d.code).html()}</td><td>${$('<div>').text(d.name).html()}</td><td>${$('<div>').text(d.unit).html()}</td><td>${$('<div>').text(d.po||'—').html()}</td><td><select class="form-select form-select-sm" name="items[${d.id}][customer_id]">${opts}</select></td><td><input type="number" class="form-control form-control-sm text-end" name="items[${d.id}][quantity]" min="0.0001" max="${d.available}" step="0.0001" required value="${d.quantity||''}"></td><td><input type="number" class="form-control form-control-sm text-end" name="items[${d.id}][cartons]" min="0" step="0.0001" value="${d.cartons||0}"></td><td><button type="button" class="btn btn-outline-danger btn-sm p-1 js-remove-gsn-line" title="{{ __('ui.common.delete') }}"><i data-feather="trash-2" class="icon-sm"></i></button></td></tr>`);window.feather&&feather.replace()}
 if(initial?.items?.length){initial.items.forEach(i=>{const p=i.production_order?.output_product||{};addLine({id:i.production_order_id,product_id:i.product_id,mo:i.production_order?.number,po:i.production_order?.buyer_po_number,customer_id:i.customer_id,style:p.style_code,code:p.code,name:p.name,unit:p.unit?.symbol||p.unit?.name,quantity:i.quantity,cartons:i.cartons,available:Number(i.quantity)})})}
 $('#gsnAddOrder').on('click',()=>orderModal.show());$(document).on('click','.js-choose-gsn-order',function(){let b=$(this);addLine({id:b.data('id'),product_id:b.data('product'),mo:b.data('mo'),po:b.data('po'),customer_id:b.data('customer'),style:b.data('style'),code:b.data('code'),name:b.data('name'),unit:b.data('unit'),available:b.data('available')});orderModal.hide()});$(document).on('click','.js-remove-gsn-line',function(){$(this).closest('tr').remove()});
 if(!noteId)$.get(@json(route('super.goods-sent-notes.number-preview'))).done(x=>$('#gsnNumber').val(x.number));
 $('#gsnForm').on('submit',function(e){e.preventDefault();let url=noteId?@json(route('super.goods-sent-notes.update',['note'=>'__ID__'])).replace('__ID__',noteId):@json(route('super.goods-sent-notes.store'));$('#gsnSave').prop('disabled',true);$.ajax({url,method:noteId?'PUT':'POST',data:$(this).serialize()}).done(()=>location.href=@json(route('super.goods-sent-notes.index'))).fail(x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'})).always(()=>$('#gsnSave').prop('disabled',false))});
});
</script>
